breach.segment:
// Ignore claims no pod has reported for more than 5 minutes before their cluster's newest sample
WHERE last_seen >= cluster_newest - 5 minutes
// Threshold: fraction of the volume used, now and in every reported minute of the last 15,
// with at least 12 of the 16 minutes reported, so a new claim or sparse data can't fire on a few samples.
| WHERE latest_utilization >= 0.9 AND min_utilization >= 0.9 AND reported_minutes >= 12
| KEEP resource.attributes.project_id, resource.attributes.location, resource.attributes.cluster_name,
       resource.attributes.namespace_name, attributes.persistentvolumeclaim_name,
       latest_utilization, min_utilization, reported_minutes, used_gib, capacity_gib, last_seen
| SORT latest_utilization DESC
